                              true && (
                              <>
                                <p>{internalSelectedCountries.name}</p>

                                <div class="graph">
                                  <BarChart
                                    chartData={
                                      internalSelectedCountries.regionDataPacketLoss
                                    }
                                  />
                                </div>
                              </>
                            )}
                          </div>
                        ),
                      )}
                    </div>
                  </>
                )}
            </Accordion.Body>
          </Accordion.Item>
        </Accordion>
      </div>
    </div>
  );
}

export default PageMLAB;
